//! Wolfram correctly-rounded sin/cos golden replay.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/sincos_golden.wls`) carries IEEE-exact input decimals with
//! correctly rounded sine/cosine values, especially k*pi/2 neighbors at
//! adjacent bit patterns and huge exponents. The checked-in MPFR corpus
//! remains the second independent implementation.
//!
//! Error bands follow the implementation's documented envelopes: the fast
//! Cody–Waite path holds 8 ULP at 1.0 scale, widening through the
//! Payne–Hanek transition to a generous bound for huge arguments. The metric
//! is |actual − expected|/EPSILON, i.e. absolute error near true zeros.

use serde::Deserialize;
use sonium_fastmath::{exp_i, sincos_scalar, sincos_with_derivatives};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    x: String,
    sin: String,
    cos: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    precision_digits: u32,
    generator: String,
    cases: Vec<Case>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram sincos fixture");
    assert_eq!(fixture.schema, "sonium-fastmath.wolfram-golden.v1");
    assert_eq!(fixture.precision_digits, 100);
    assert!(fixture.generator.contains("Wolfram Engine"));
    fixture
}

fn input_of(case: &Case) -> f64 {
    if case.name == "neg_zero" {
        -0.0
    } else {
        case.x.parse().expect("fixture input is a decimal")
    }
}

/// Envelope in EPSILON-at-one units by argument magnitude band.
fn envelope(x: f64) -> f64 {
    let magnitude = x.abs();
    if magnitude <= 8.0 {
        8.0
    } else if magnitude <= 1e7 {
        16.0
    } else {
        128.0
    }
}

fn scaled_error(actual: f64, expected: f64) -> f64 {
    if actual == expected {
        return 0.0;
    }
    if !actual.is_finite() || !expected.is_finite() {
        return f64::INFINITY;
    }
    (actual - expected).abs() / f64::EPSILON
}

fn check_pair(label: &str, actual: f64, expected: f64, allowed: f64) {
    // The sign is asserted only above the error band: within rounding noise
    // of zero (e.g. cos near an odd multiple of pi/2) the correctly rounded
    // sign is meaningless and only the absolute error counts.
    if expected.abs() > allowed * f64::EPSILON {
        assert_eq!(
            actual.is_sign_negative(),
            expected.is_sign_negative(),
            "{label}: sign mismatch {actual:e} vs {expected:e}"
        );
    }
    let error = scaled_error(actual, expected);
    assert!(
        error <= allowed,
        "{label}: {error} ULP > {allowed} ULP ({actual:e} vs {expected:e})"
    );
}

#[test]
fn sincos_scalar_matches_wolfram_golden() {
    let fixture = parse_fixture();
    assert_eq!(fixture.cases.len(), 34);
    for case in &fixture.cases {
        let x = input_of(case);
        let allowed = envelope(x);
        let expected_sin: f64 = case.sin.parse().expect("fixture sin is a decimal");
        let expected_cos: f64 = case.cos.parse().expect("fixture cos is a decimal");
        let (sin, cos) = sincos_scalar(x);
        check_pair(&format!("{} sin", case.name), sin, expected_sin, allowed);
        check_pair(&format!("{} cos", case.name), cos, expected_cos, allowed);
    }
    // Exact signed zeros are pinned by bits: the band rule above deliberately
    // skips sign checks at zero.
    assert_eq!(sincos_scalar(0.0).0.to_bits(), 0x0000000000000000);
    assert_eq!(sincos_scalar(-0.0).0.to_bits(), 0x8000000000000000);
    assert_eq!(sincos_scalar(0.0).1.to_bits(), 0x3ff0000000000000);
    assert_eq!(sincos_scalar(-0.0).1.to_bits(), 0x3ff0000000000000);
}

#[test]
fn sincos_derivatives_match_wolfram_golden() {
    let fixture = parse_fixture();
    for case in &fixture.cases {
        let x = input_of(case);
        let allowed = envelope(x);
        let expected_sin: f64 = case.sin.parse().expect("fixture sin is a decimal");
        let expected_cos: f64 = case.cos.parse().expect("fixture cos is a decimal");
        let derivatives = sincos_with_derivatives(x);
        check_pair(
            &format!("{} d_sin==cos", case.name),
            derivatives.d_sin,
            expected_cos,
            allowed,
        );
        check_pair(
            &format!("{} d_cos==-sin", case.name),
            derivatives.d_cos,
            -expected_sin,
            allowed,
        );
    }
}

#[test]
fn exp_i_matches_wolfram_golden() {
    let fixture = parse_fixture();
    for case in &fixture.cases {
        let x = input_of(case);
        let allowed = envelope(x);
        let expected_sin: f64 = case.sin.parse().expect("fixture sin is a decimal");
        let expected_cos: f64 = case.cos.parse().expect("fixture cos is a decimal");
        let value = exp_i(x);
        check_pair(
            &format!("{} exp_i.re", case.name),
            value.re,
            expected_cos,
            allowed,
        );
        check_pair(
            &format!("{} exp_i.im", case.name),
            value.im,
            expected_sin,
            allowed,
        );
    }
}
